#!/bin/bash
# Build the report: merge bib fixes, compile 3x with bibtex. Aux files go to build/, the PDF to report/main.pdf.
#   sections/<slug>.tex   hand-written dataset sections (see WRITER_GUIDE.md)
#   traj/<slug>.tex       generated by scripts/render_traj.py
#   assets/figures/       generated by scripts/make_figures.py
#   assets/tables/        small \input snippets used by sections/overview.tex
#   bib/                  refs.bib + bibfix/*.bib -> refs_merged.bib (generated)
set -e
export PATH=$HOME/.TinyTeX/bin/x86_64-linux:$PATH
cd "$(dirname "$0")"
mkdir -p build
python3 ../scripts/merge_bib.py bib/refs.bib bib/bibfix bib/refs_merged.bib
TEX="pdflatex -interaction=nonstopmode -output-directory=build"
$TEX -halt-on-error main.tex >/dev/null || { grep -A3 "^!" build/main.log | head -30; exit 1; }
bibtex build/main >/dev/null || true   # run from report/ so bib/refs_merged.bib resolves
$TEX main.tex >/dev/null
$TEX main.tex >/dev/null
cp build/main.pdf main.pdf
grep -E "^!" build/main.log | head; grep -c "Overfull" build/main.log || true
grep -E "Output written" build/main.log
